7	/* Cửa sổ nhà cao tầng sinh bằng shader theo tọa độ thế giới (không kéo giãn khi đổi chiều cao) */
8	const f1 = (n: number) => n.toFixed(4);
9	/* Đèn đêm theo từng tòa (perBuilding): vBId, vBSize là hằng trong một instance; không chia cho kích thước nên instance scale 0 vẫn an toàn */
10	function cityNightGlsl() {
11	  const N = CONFIG.cityNight;
12	  return `{ vec2 cl; float wm = winMask(cl);
13	          float h = bHash(cl + floor(vBPos.xz * 0.02) * 7.13);
14	          float s1 = bHash(vBId + 3.7), s2 = bHash(vBId + 11.3), s3 = bHash(vBId + 29.1);
15	          float tower = step(${f1(N.towerH)}, vBSize.y);
16	          vec3 lit = s1 < 0.25 ? vec3(1.0, 0.55, 0.14) : s1 < 0.5 ? vec3(1.0, 0.46, 0.09) : s1 < 0.75 ? vec3(1.0, 0.38, 0.06) : vec3(1.0, 0.64, 0.22);
17	          if (tower > 0.5 && s2 < ${f1(N.coolShare)}) lit = s3 < 0.5 ? vec3(0.04, 0.28, 1.0) : vec3(0.02, 0.72, 0.62);
18	          float on = step(1.0 - mix(${f1(N.lowLit)}, ${f1(N.towerLit)}, tower), h);
19	          totalEmissiveRadiance += wm * on * lit * uNight * mix(${f1(N.lowGain)}, ${f1(N.towerGain)}, tower);
20	          if (tower > 0.5 && abs(vBNrm.y) < 0.6) {
21	            float top = vBBase + vBSize.y, fromTop = top - vBPos.y;
22	            float axis = abs(vBNrm.x) > 0.5 ? abs(vBPos.z - vBId.y) - vBSize.z * 0.5 : abs(vBPos.x - vBId.x) - vBSize.x * 0.5;
23	            float band = step(fromTop, ${f1(N.ledBand)});
24	            float edge = step(-${f1(N.ledWidth)}, axis) * step(fromTop, vBSize.y * ${f1(N.ledEdgeFrac)});
25	            vec3 led = s3 < 0.25 ? vec3(0.70, 0.04, 1.0) : s3 < 0.5 ? vec3(1.0, 0.03, 0.42) : s3 < 0.75 ? vec3(0.04, 0.45, 1.0) : vec3(1.0, 0.55, 0.05);
26	            totalEmissiveRadiance += max(band, edge) * led * uNight * ${f1(N.ledGain)};
27	          } }`;
28	}
29	
30	export function patchWindows(mat: Mat, opts: { perBuilding?: boolean } = {}) {
31	  const per = !!opts.perBuilding;
32	  mat.customProgramCacheKey = () => (per ? 'windows-city' : 'windows');
33	  mat.onBeforeCompile = (sh) => {
34	    sh.uniforms.uNight = shared.uNight;
35	    sh.vertexShader = sh.vertexShader
36	      .replace('#include <common>', '#include <common>\nvarying vec3 vBPos; varying vec3 vBNrm;' + (per ? ' varying vec2 vBId; varying vec3 vBSize; varying float vBBase;' : ''))
37	      .replace('#include <fog_vertex>', `#include <fog_vertex>
38	        { vec4 bp = vec4(transformed, 1.0); vec3 bn = objectNormal;
39	        #ifdef USE_INSTANCING
40	          bp = instanceMatrix * bp; bn = mat3(instanceMatrix) * bn;
41	        #endif
42	          vBPos = (modelMatrix * bp).xyz; vBNrm = normalize(mat3(modelMatrix) * bn); }` + (per ? `
43	        #ifdef USE_INSTANCING
44	          { vec4 o = modelMatrix * instanceMatrix[3]; vBId = o.xz; vBBase = o.y;
45	            vBSize = vec3(length(instanceMatrix[0].xyz), length(instanceMatrix[1].xyz), length(instanceMatrix[2].xyz)); }
46	        #endif` : ''));
47	    sh.fragmentShader = sh.fragmentShader
48	      .replace('#include <common>', `#include <common>
49	        varying vec3 vBPos; varying vec3 vBNrm; uniform float uNight;${per ? ' varying vec2 vBId; varying vec3 vBSize; varying float vBBase;' : ''}
50	        float bHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
51	        float winMask(out vec2 cell){
52	          float side = 1.0 - step(0.6, abs(vBNrm.y));
53	          float along = abs(vBNrm.x) > 0.5 ? vBPos.z : vBPos.x;
54	          vec2 g = vec2(along / 3.2, vBPos.y / 3.4);
55	          cell = floor(g); vec2 f = fract(g);
56	          return side * step(0.16, f.x) * step(f.x, 0.84) * step(0.22, f.y) * step(f.y, 0.82) * step(5.5, vBPos.y);
57	        }`)
58	      .replace('#include <map_fragment>', `#include <map_fragment>
59	        { vec2 cl; float wm = winMask(cl);
60	          diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.20, 0.29, 0.36), wm * 0.82); }`)
61	      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
62	        ` + (per ? cityNightGlsl() : `{ vec2 cl; float wm = winMask(cl);
63	          float h = bHash(cl + floor(vBPos.xz * 0.02) * 7.13);
64	          vec3 lit = mix(vec3(1.0, 0.78, 0.46), vec3(0.75, 0.88, 1.0), step(0.8, h));
65	          totalEmissiveRadiance += wm * step(0.42, h) * lit * uNight * 1.3; }`));
66	  };
67	}
68	
69	/* Ánh vàng nhẹ về đêm cho khối trơn ở xa (level far của LOD nhà): chỉ mặt bên, để đường chân trời không tối hẳn */
70	export function patchFarGlow(mat: Mat) {
71	  mat.customProgramCacheKey = () => 'far-glow';
72	  mat.onBeforeCompile = (sh) => {
73	    sh.uniforms.uNight = shared.uNight;
74	    sh.vertexShader = sh.vertexShader
75	      .replace('#include <common>', '#include <common>\nvarying float vFarNy;')
76	      .replace('#include <fog_vertex>', '#include <fog_vertex>\n vFarNy = abs(objectNormal.y);');
77	    sh.fragmentShader = sh.fragmentShader
78	      .replace('#include <common>', '#include <common>\nuniform float uNight; varying float vFarNy;')
79	      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
80	        totalEmissiveRadiance += vec3(1.0, 0.75, 0.42) * ${f1(CONFIG.cityNight.farGlow)} * uNight * (1.0 - step(0.6, vFarNy));`);
81	  };
82	}
83	
84	/* ======================================================================
85	   Shader bổ sung cho các cầu: vân bê tông, vệt nước bám, LED đổi màu theo bảng màu / pattern
86	   ====================================================================== */
87	export const LED_PALETTES = {
88	  sea: [[0.10, 0.35, 1.00], [0.55, 0.18, 1.00], [1.00, 0.22, 0.62], [0.12, 1.00, 0.55]],  // xanh dương → tím → hồng → xanh lá
89	  sail: [[1.00, 0.08, 0.10], [1.00, 0.20, 0.50], [0.60, 0.16, 1.00], [0.12, 0.38, 1.00]], // đỏ → hồng → tím → xanh ("cánh buồm đỏ")
90	  rainbow: [[1.00, 0.12, 0.10], [1.00, 0.78, 0.10], [0.10, 1.00, 0.35], [0.15, 0.40, 1.00]] // cầu vồng (Cầu sông Hàn)
91	};
92	export type PaletteName = keyof typeof LED_PALETTES;
93	const glslVec3 = (c: number[]) => `vec3(${c.map((v) => v.toFixed(2)).join(', ')})`;
94	
95	export interface BridgePatchOptions {
96	  noise?: boolean;
97	  wet?: boolean;
98	  led?: number;                  // cường độ
99	  mode?: 0 | 1;                  // 0: theo trục cầu, 1: đèn hắt tháp
100	  palette?: PaletteName;
101	  pattern?: { value: number };   // uniform chọn pattern
102	  originX?: number;              // sóng chạy ra xa điểm này
103	  originZ?: number;
104	  floodTop?: number;             // m, cho mode 1
105	  floodBase?: number;
106	  weather?: boolean;             // mặt ướt khi mưa: đọc weatherU.uWet (0 = không đổi gì)
107	  sag?: 'cable' | 'hanger';      // võng cáp chủ Thuận Phước khi nóng (weather/summer.ts): đọc weatherU.uSagTp (0 = không đổi gì); hanger chỉ dịch đầu trên
108	  sway?: SwayKind;               // dây lắc theo gió (chỉ InstancedMesh dựng bằng segmentMatrix): đọc weatherU.uSwayTp/Ttl/Sh (0 = không đổi gì)
109	}
110	export type SwayKind = 'tp' | 'ttl' | 'sh';
111	const SWAY_U = { tp: weatherU.uSwayTp, ttl: weatherU.uSwayTtl, sh: weatherU.uSwaySh };
112	
113	/* Dây lắc theo gió (mục 4.5): dịch SAU khi nhân instanceMatrix/modelMatrix (không gian thế giới — segmentMatrix co bán kính nên dịch cục bộ bị thu nhỏ).
114	   Dạng sin(π·t), t = position.y + 0.5 của CylinderGeometry (hai đầu cố định) — hình trụ phải có heightSegments > 1 (CONFIG.weather.wind.cableSegs), dây 1 đoạn thì sin = 0 ở mọi đỉnh, không lắc. Hướng chính: thành phần gió vuông góc với dây, thêm 35 % vuông góc thứ hai (quỹ đạo elip).
115	   Biên độ (m, đã phóng đại) do weather/wind.ts tính; = 0 thì nhánh không chạy (ảnh preset `now` trùng từng điểm ảnh). */
116	const swayVertex = (omega: number) => `#include <project_vertex>
117	  #ifdef USE_INSTANCING
118	  if (uSway > 0.0) {
119	    vec3 swAx = mat3(modelMatrix) * instanceMatrix[1].xyz; float swLen = length(swAx); swAx /= swLen;
120	    vec3 swW = vec3(uWindDir.x, 0.0, uWindDir.y), swD = swW - swAx * dot(swW, swAx); float swL = length(swD);
121	    swD = swL > 1e-3 ? swD / swL : vec3(0.0, 1.0, 0.0);
122	    vec3 swE = cross(swAx, swD), swC = (modelMatrix * vec4(instanceMatrix[3].xyz, 1.0)).xyz;
123	    float swPh = dot(swC, vec3(0.071, 0.023, 0.113)), swT = clamp(position.y + 0.5, 0.0, 1.0);
124	    float swA = sin(3.14159265 * swT) * uSway * min(1.0, swLen / ${CONFIG.weather.wind.refLen.toFixed(1)});
125	    vec3 swDisp = swA * (swD * sin(uTime * ${omega.toFixed(2)} + swPh) + swE * 0.35 * sin(uTime * ${(omega * 1.37).toFixed(2)} + swPh * 1.7));
126	    mvPosition.xyz += mat3(viewMatrix) * swDisp; gl_Position = projectionMatrix * mvPosition;
127	  }
128	  #endif`;
129	/* Võng cáp chủ khi nóng (mục 4.7): dịch y theo Δf·sin(π·u), u = vị trí dọc nhịp chính (ngoài nhịp chính = 0). Hanger: chỉ đầu trên (position.y = −0,5, xem segmentMatrix(top, bot)) đi xuống. */
130	const sagVertex = (kind: 'cable' | 'hanger') => `
131	  if (uSagTp != 0.0) {
132	    vec4 sgL = vec4(transformed, 1.0);
133	    #ifdef USE_INSTANCING
134	      sgL = instanceMatrix * sgL;
135	    #endif
136	    float sgX = (modelMatrix * sgL).x, sgU = clamp((sgX + ${(CONFIG.thuanPhuoc.mainSpan / 2).toFixed(2)}) / ${CONFIG.thuanPhuoc.mainSpan.toFixed(2)}, 0.0, 1.0);
137	    float sgW = ${kind === 'hanger' ? 'clamp(0.5 - position.y, 0.0, 1.0)' : '1.0'};
138	    mvPosition.xyz += mat3(viewMatrix) * vec3(0.0, -uSagTp * sin(3.14159265 * sgU) * sgW, 0.0); gl_Position = projectionMatrix * mvPosition;
139	  }`;
140	export function bridgePatch<M extends Mat>(mat: M, opt: BridgePatchOptions): M {
141	  const pal = LED_PALETTES[opt.palette || 'sea'];
142	  const key = ['bp', opt.noise ? 1 : 0, opt.wet ? 1 : 0, opt.led || 0, opt.mode || 0, opt.palette || 'sea',
143	    opt.pattern ? 1 : 0, opt.originX ?? 'n', opt.originZ ?? 'n', opt.floodTop ?? 95, opt.floodBase ?? 12].join('-') + (opt.weather ? '-w' : '') + (opt.sway ? '-s' + opt.sway : '') + (opt.sag ? '-g' + opt.sag : '');   // tắt weather/sway: key cũ giữ nguyên
144	  mat.customProgramCacheKey = () => key;
145	  mat.onBeforeCompile = (sh) => {
146	    sh.uniforms.uTime = shared.uTime; sh.uniforms.uNight = shared.uNight;
147	    if (opt.pattern) sh.uniforms.uPattern = opt.pattern;
148	    if (opt.weather) sh.uniforms.uWet = weatherU.uWet;
149	    if (opt.sag) sh.uniforms.uSagTp = weatherU.uSagTp;
150	    if (opt.sway) { sh.uniforms.uSway = SWAY_U[opt.sway]; sh.uniforms.uWindDir = weatherU.uWindDir; }
151	    sh.vertexShader = sh.vertexShader
152	      .replace('#include <common>', '#include <common>\nvarying vec3 vBW;' + (opt.sway ? '\nuniform float uTime; uniform float uSway; uniform vec2 uWindDir;' : '') + (opt.sag ? '\nuniform float uSagTp;' : ''))
153	      .replace('#include <project_vertex>', (opt.sway ? swayVertex(CONFIG.weather.wind[opt.sway].omega) : '#include <project_vertex>') + (opt.sag ? sagVertex(opt.sag) : ''))
154	      .replace('#include <fog_vertex>', `#include <fog_vertex>
155	        { vec4 bw = vec4(transformed, 1.0);
156	        #ifdef USE_INSTANCING
157	          bw = instanceMatrix * bw;
158	        #endif
159	          vBW = (modelMatrix * bw).xyz; }`);
160	    let frag = sh.fragmentShader.replace('#include <common>', `#include <common>
161	      varying vec3 vBW; uniform float uTime; uniform float uNight; ${opt.pattern ? 'uniform float uPattern;' : ''} ${opt.weather ? 'uniform float uWet;' : ''}
162	      float bpHash(vec3 p){ p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
163	      float bpNoise(vec3 x){ vec3 i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f);
164	        return mix(mix(mix(bpHash(i), bpHash(i + vec3(1,0,0)), f.x), mix(bpHash(i + vec3(0,1,0)), bpHash(i + vec3(1,1,0)), f.x), f.y),
165	                   mix(mix(bpHash(i + vec3(0,0,1)), bpHash(i + vec3(1,0,1)), f.x), mix(bpHash(i + vec3(0,1,1)), bpHash(i + vec3(1,1,1)), f.x), f.y), f.z); }
166	      vec3 bpPal(float s){ s = fract(s) * 4.0; float i = floor(s), f = smoothstep(0.0, 1.0, fract(s));
167	        vec3 c0 = ${glslVec3(pal[0])}, c1 = ${glslVec3(pal[1])}, c2 = ${glslVec3(pal[2])}, c3 = ${glslVec3(pal[3])};
168	        vec3 a = i < 1.0 ? c0 : i < 2.0 ? c1 : i < 3.0 ? c2 : c3;
169	        vec3 b = i < 1.0 ? c1 : i < 2.0 ? c2 : i < 3.0 ? c3 : c0;
170	        return mix(a, b, f); }`);
171	    let after = '';
172	    if (opt.noise) after += `
173	        float bpN = bpNoise(vBW * 0.16) * 0.6 + bpNoise(vBW * 0.85) * 0.4;
174	        diffuseColor.rgb *= 0.86 + 0.22 * bpN;`;
175	    if (opt.wet) after += `
176	        { vec3 wetC = vBW.y < -0.4 ? vec3(0.42, 0.44, 0.40) : vec3(0.56, 0.60, 0.52);
177	          diffuseColor.rgb *= mix(wetC, vec3(1.0), smoothstep(1.7, 2.4, vBW.y)); }`;
178	    // Mặt ướt: uWet = 0 thì nhánh không chạy (ảnh preset `now` trùng từng điểm ảnh); mặt hướng lên ướt hơn mặt đứng
179	    if (opt.weather) after += `
180	        float bpWet = 0.0;
181	        if (uWet > 0.0) { bpWet = uWet * mix(0.6, 1.0, step(0.0, vBW.y)); diffuseColor.rgb *= 1.0 - ${(1 - CONFIG.weather.wetness.bridgeDarken).toFixed(3)} * bpWet; }`;
182	    if (after) frag = frag.replace('#include <map_fragment>', `#include <map_fragment>${after}`);
183	    if (opt.noise) frag = frag.replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
184	        roughnessFactor = clamp(roughnessFactor + (bpN - 0.5) * 0.18, 0.0, 1.0);`);
185	    if (opt.weather) frag = frag.replace('#include <lights_physical_fragment>', `if (uWet > 0.0) roughnessFactor = mix(roughnessFactor, min(roughnessFactor, ${CONFIG.weather.wetness.bridgeRough.toFixed(3)}), bpWet);
186	        #include <lights_physical_fragment>`);
187	    if (opt.led) {
188	      const L = opt.led.toFixed(2), fTop = (opt.floodTop ?? 95).toFixed(1), fBase = (opt.floodBase ?? 12).toFixed(1);
189	      // originX: sóng chạy ra xa điểm này theo trục X; thêm originZ: theo khoảng cách ngang (dùng cho nhịp quay)
190	      const coord = opt.originZ !== undefined ? `length(vec2(vBW.x - (${opt.originX.toFixed(1)}), vBW.z - (${opt.originZ.toFixed(1)})))`
191	        : opt.originX !== undefined ? `abs(vBW.x - (${opt.originX.toFixed(1)}))` : 'vBW.x';
192	      let body: string;
193	      if (opt.mode === 1 && !opt.pattern) {          // tháp: đèn hắt từ chân lên, dải màu chạy lên đỉnh
194	        body = `float s = vBW.y * 0.006 + vBW.x * 0.0025 - uTime * 0.07;
195	           float flood = 0.35 + 0.65 * smoothstep(${fTop}, ${fBase}, vBW.y);
196	           float band = 0.75 + 0.25 * sin(vBW.y * 0.25 - uTime * 2.0);
197	           totalEmissiveRadiance += bpPal(s) * flood * band * uNight * ${L};`;
198	      } else if (!opt.pattern) {                     // cáp / dải đèn: màu trượt dọc cầu, xung sáng chạy
199	        body = `float s = ${coord} * 0.0025 - uTime * 0.07;
200	           float pulse = 0.55 + 0.45 * sin(${coord} * 0.045 - uTime * 2.2);
201	           totalEmissiveRadiance += bpPal(s) * pulse * uNight * ${L};`;
202	      } else {                                       // có chọn pattern: 0 tĩnh, 1 chuyển màu chậm, 2 sóng màu chạy dọc dây
203	        const c = opt.mode === 1 ? 'vBW.y' : coord;
204	        const flood = opt.mode === 1 ? `0.35 + 0.65 * smoothstep(${fTop}, ${fBase}, vBW.y)` : '1.0';
205	        body = `float s; float pulse;
206	           if (uPattern < 0.5) { s = 0.06; pulse = 1.0; }
207	           else if (uPattern < 1.5) { s = uTime * 0.025; pulse = 1.0; }
208	           else { s = ${c} * 0.004 - uTime * 0.09; pulse = 0.5 + 0.5 * sin(${c} * 0.06 - uTime * 2.6); }
209	           totalEmissiveRadiance += bpPal(s) * pulse * (${flood}) * uNight * ${L};`;
210	      }
211	      frag = frag.replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>\n{ ${body} }`);
212	    }
213	    sh.fragmentShader = frag;
214	  };
215	  return mat;
216	}
