1	import * as THREE from 'three';
2	import { Water } from 'three/addons/objects/Water.js';
3	import { scene } from './renderer';
4	import { rng } from '../common/math';
5	import { CONFIG } from '../config';
6	import { shared } from './shared';
7	
8	/* ============================ Mặt nước sông Hàn ============================ */
9	export let water: Water;
10	
11	function makeWaterNormals() {
12	  const S = 256, d = new Uint8Array(S * S * 4);
13	  // Tổng nhiều sóng tần số nguyên, pha ngẫu nhiên → lát gạch liền mạch, không lộ hoa văn
14	  const waves: [number, number, number, number][] = []; const wr = rng(77);
15	  for (let i = 0; i < 28; i++) {
16	    const fx = Math.round((wr() - 0.5) * 2 * (3 + i)), fy = Math.round((wr() - 0.5) * 2 * (3 + i));
17	    if (fx === 0 && fy === 0) continue;
18	    waves.push([fx, fy, wr() * Math.PI * 2, 1 / Math.hypot(fx, fy)]);
19	  }
20	  const hgt = (x: number, y: number) => {
21	    const u = x / S * Math.PI * 2, v = y / S * Math.PI * 2; let h = 0;
22	    for (const [fx, fy, ph, a] of waves) h += Math.sin(u * fx + v * fy + ph) * a;
23	    return h;
24	  };
25	  // Lưới độ cao tính một lần, rộng thêm 1 điểm ảnh mỗi bên (cùng công thức nên trùng từng byte với cách gọi hgt 4 lần/điểm ảnh, nhanh ≈ 3,5×; D-018)
26	  const N = S + 2, H = new Float64Array(N * N);
27	  for (let y = -1; y <= S; y++) for (let x = -1; x <= S; x++) if (!((x < 0 || x === S) && (y < 0 || y === S))) H[(y + 1) * N + x + 1] = hgt(x, y);
28	  const at = (x: number, y: number) => H[(y + 1) * N + x + 1];
29	  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
30	    const dx = (at(x + 1, y) - at(x - 1, y)) * 6, dy = (at(x, y + 1) - at(x, y - 1)) * 6;
31	    const l = Math.hypot(dx, dy, 1), i = (y * S + x) * 4;
32	    d[i] = (-dx / l * 0.5 + 0.5) * 255; d[i + 1] = (-dy / l * 0.5 + 0.5) * 255; d[i + 2] = (1 / l * 0.5 + 0.5) * 255; d[i + 3] = 255;
33	  }
34	  const t = new THREE.DataTexture(d, S, S, THREE.RGBAFormat);
35	  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.needsUpdate = true;
36	  return t;
37	}
38	/* Vệt đèn dài trên sông về đêm: lấy thêm mẫu ảnh phản chiếu dọc trục V, chỉ cộng phần sáng hơn ngưỡng; uNight = 0 giữ nguyên hình ảnh ban ngày */
39	const REFLECTION_LINE = 'vec3 reflectionSample = vec3( texture2D( mirrorSampler, mirrorCoord.xy / mirrorCoord.w + distortion ) );';
40	function patchNightStreak(mat: THREE.ShaderMaterial) {
41	  if (!mat.fragmentShader.includes(REFLECTION_LINE)) throw new Error('Water.js đã đổi: không tìm thấy dòng lấy mẫu phản chiếu');
42	  const S = CONFIG.cityNight.streak;
43	  mat.uniforms.uNight = shared.uNight;
44	  mat.fragmentShader = 'uniform float uNight;\n' + mat.fragmentShader.replace(REFLECTION_LINE, `${REFLECTION_LINE}
45	    if ( uNight > 0.6 ) {
46	      vec3 streak = vec3( 0.0 ); float weight = 0.0;
47	      for ( int i = 1; i <= ${S.taps}; i ++ ) {
48	        float t = float( i ) / ${S.taps.toFixed(1)}, w = 1.0 - t * 0.7;
49	        vec3 c = vec3( texture2D( mirrorSampler, mirrorCoord.xy / mirrorCoord.w + distortion * ( 1.0 + t ) + vec2( 0.0, STREAK_SIGN * t * ${S.reach.toFixed(4)} ) ) );
50	        streak += max( c - ${S.threshold.toFixed(3)}, 0.0 ) * w; weight += w;
51	      }
52	      reflectionSample += streak / weight * ${S.gain.toFixed(3)} * smoothstep( 0.6, 1.0, uNight );
53	    }`).replace(/STREAK_SIGN/g, '1.0');
54	}
55	
56	export function buildWater() {
57	  const g = new THREE.PlaneGeometry(40000, 40000);
58	  water = new Water(g, {
59	    textureWidth: 512, textureHeight: 512, waterNormals: makeWaterNormals(),
60	    sunDirection: new THREE.Vector3(0, 1, 0), sunColor: 0xffffff, waterColor: 0x2c5a4f,
61	    distortionScale: 2.4, fog: true
62	  });
63	  water.rotation.x = -Math.PI / 2;
64	  water.material.uniforms.size.value = 0.6;
65	  patchNightStreak(water.material as THREE.ShaderMaterial);
66	  scene.add(water);
67	  // Phản chiếu theo bậc chất lượng (D-018): every = 1 như gốc (vẽ lại cả cảnh vào target 512² mỗi khung), n > 1 vẽ mỗi n khung (giữ ảnh cũ ở giữa),
