74	    if (every > 0) {
75	      if (mirror.value !== mirrorTex) mirror.value = mirrorTex;
76	      if (every === 1 || n++ % every === 0) draw.apply(this, args);
77	      return;
78	    }
79	    if (mirror.value !== flatTex) mirror.value = flatTex;
