81	    const r = Math.round(c.r * 255), g = Math.round(c.g * 255), b = Math.round(c.b * 255);
82	    if (d[0] !== r || d[1] !== g || d[2] !== b) { d[0] = r; d[1] = g; d[2] = b; d[3] = 255; flatTex.needsUpdate = true; }
