7	/* Cửa sổ nhà cao tầng sinh bằng shader theo tọa độ thế giới (không kéo giãn khi đổi chiều cao) */
8	const f1 = (n: number) => n.toFixed(4);
9	/* Đèn đêm theo từng tòa (perBuilding): vBId, vBSize là hằng trong một instance; không chia cho kích thước nên instance scale 0 vẫn an toàn */
10	function cityNightGlsl() {
11	  const N = CONFIG.cityNight;
12	  return `{ vec2 cl; float wm = winMask(cl);
13	          float h = bHash(cl + floor(vBPos.xz * 0.02) * 7.13);
14	          float s1 = bHash(vBId + 3.7), s2 = bHash(vBId + 11.3), s3 = bHash(vBId + 29.1);
15	          float tower = step(${f1(N.towerH)}, vBSize.y);
16	          vec3 lit = s1 < 0.25 ? vec3(1.0, 0.55, 0.14) : s1 < 0.5 ? vec3(1.0, 0.46, 0.09) : s1 < 0.75 ? vec3(1.0, 0.38, 0.06) : vec3(1.0, 0.64, 0.22);
17	          if (tower > 0.5 && s2 < ${f1(N.coolShare)}) lit = s3 < 0.5 ? vec3(0.04, 0.28, 1.0) : vec3(0.02, 0.72, 0.62);
18	          float on = step(1.0 - mix(${f1(N.lowLit)}, ${f1(N.towerLit)}, tower), h);
19	          totalEmissiveRadiance += wm * on * lit * uNight * mix(${f1(N.lowGain)}, ${f1(N.towerGain)}, tower);
20	          if (tower > 0.5 && abs(vBNrm.y) < 0.6) {
21	            float top = vBBase + vBSize.y, fromTop = top - vBPos.y;
22	            float axis = abs(vBNrm.x) > 0.5 ? abs(vBPos.z - vBId.y) - vBSize.z * 0.5 : abs(vBPos.x - vBId.x) - vBSize.x * 0.5;
23	            float band = step(fromTop, ${f1(N.ledBand)});
24	            float edge = step(-${f1(N.ledWidth)}, axis) * step(fromTop, vBSize.y * ${f1(N.ledEdgeFrac)});
25	            vec3 led = s3 < 0.25 ? vec3(0.70, 0.04, 1.0) : s3 < 0.5 ? vec3(1.0, 0.03, 0.42) : s3 < 0.75 ? vec3(0.04, 0.45, 1.0) : vec3(1.0, 0.55, 0.05);
26	            totalEmissiveRadiance += max(band, edge) * led * uNight * ${f1(N.ledGain)};
27	          } }`;
28	}
