+  // Ẩn giao diện để chỉ đo khung cảnh
+  await page.evaluate(() => document.querySelectorAll('body *').forEach((e) => { if (!e.matches('canvas') && !e.querySelector('canvas')) e.style.visibility = 'hidden'; }));
