2	import { scene, renderer } from './renderer';
3	import { shared } from './shared';
4	import { MAT } from './materials';
5	import { sun, hemi, moon, bridgeLights } from './lights';
6	import { setSun, stars, clouds } from './sky';
7	import { water } from './water';
8	import { lerp, clamp } from '../common/math';
9	import { vHead, vTail } from '../environment/traffic';
10	
11	/* ============================ Ngày / đêm ============================ */
12	/* night: giá trị hiện tại (0 ngày → 1 đêm), target: giá trị người xem chọn; night tiến dần về target */
13	export const dayNight = { night: 0, target: 0 };
14	
15	const C_FOG_DAY = new THREE.Color(0xcfdde6), C_FOG_NIGHT = new THREE.Color(0x0b1424);
16	const C_HEMI_DAY = new THREE.Color(0xcfe6ff), C_HEMI_NIGHT = new THREE.Color(0x2a3a66);
17	const C_WATER_DAY = new THREE.Color(0x2c5a4f), C_WATER_NIGHT = new THREE.Color(0x08181b);
18	const C_BULB_DAY = new THREE.Color(0x9a9890), C_BULB_NIGHT = new THREE.Color(2.4, 1.9, 1.1);
19	
20	export function applyNight(m: number, time: number) {
21	  shared.uNight.value = m;
22	  setSun(lerp(40, -7, m), 205);
23	  sun.intensity = 3.0 * clamp(1 - m * 1.15, 0, 1);
24	  moon.intensity = 0.35 * m;
25	  hemi.intensity = lerp(0.9, 0.22, m);
26	  hemi.color.copy(C_HEMI_DAY).lerp(C_HEMI_NIGHT, m);
27	  (scene.fog as THREE.FogExp2).color.copy(C_FOG_DAY).lerp(C_FOG_NIGHT, m);
28	  scene.environmentIntensity = lerp(1, 0.14, m);
29	  renderer.toneMappingExposure = lerp(0.55, 0.8, m);
30	  water.material.uniforms.waterColor.value.copy(C_WATER_DAY).lerp(C_WATER_NIGHT, m);
31	  water.material.uniforms.sunColor.value.setRGB(lerp(1, 0.25, m), lerp(1, 0.3, m), lerp(1, 0.45, m));
32	  stars.material.opacity = clamp((m - 0.4) / 0.6, 0, 1);
33	  clouds.material.opacity = lerp(0.85, 0.12, m);
34	  MAT.bulb.color.copy(C_BULB_DAY).lerp(C_BULB_NIGHT, m);
35	  MAT.boatCabin.emissiveIntensity = m * 1.4;
36	  MAT.pupil.emissiveIntensity = m * 2.5;
37	  MAT.eye.emissiveIntensity = 0.05 + m * 0.4;
38	  vHead.visible = vTail.visible = m > 0.3;
39	  // Đèn dọc cầu nhấp nháy nhẹ theo sin(time)
40	  bridgeLights.forEach((l) => { l.intensity = l.userData.base * m * (0.82 + 0.18 * Math.sin(time * 2.2 + l.userData.phase)); });
41	}
42	/* Một bước chuyển ngày ↔ đêm mỗi khung hình */
43	export function stepNight(dt: number) {
44	  dayNight.night += (dayNight.target - dayNight.night) * Math.min(1, dt * 1.6);
45	  if (Math.abs(dayNight.target - dayNight.night) < 0.001) dayNight.night = dayNight.target;
46	}
